"use strict";(globalThis.webpackChunkmythogen_engine_blog=globalThis.webpackChunkmythogen_engine_blog||[]).push([[3787],{66152(e,t,n){n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>r,default:()=>d,frontMatter:()=>a,metadata:()=>o,toc:()=>l});var i=n(74848),s=n(28453);const a={title:"HBM Is Not the Next TSMC: The Structural Chasm Between Memory and Logic",date:new Date("2026-05-26T00:00:00.000Z"),lang:"en",section:"sober-record",topic:"t-hardware",article_tags:{zh:["\u8b77\u57ce\u6cb3","\u5546\u696d\u6a21\u5f0f","\u7b97\u529b\u7af6\u8cfd","NVIDIA","\u51fa\u53e3\u7ba1\u5236"],en:["moat","business-model","compute-race","nvidia","export-control"]},keywords:["HBM","TSMC","SK Hynix","memory cycle","semiconductor industry structure"],summary:"Dismantling the 'HBM = next TSMC' narrative across three dimensions \u2014 business model, industry cyclicality, and geopolitics \u2014 and warning of valuation misalignment at the cycle peak.",status:"published",reading_time:18,description:"Dismantling the 'HBM = next TSMC' narrative across three dimensions \u2014 business model, industry cyclicality, and geopolitics \u2014 and warning of valuation misalignment at the cycle peak."},r="HBM Is Not the Next TSMC: The Structural Chasm Between Memory and Logic",o={id:"TechNotes/HBM \u4e0d\u662f\u4e0b\u4e00\u500b\u53f0\u7a4d\u96fb\uff1a\u8a18\u61b6\u9ad4\u8207\u908f\u8f2f\u6676\u7247\u7684\u7d50\u69cb\u6027\u9d3b\u6e9d",title:"HBM Is Not the Next TSMC: The Structural Chasm Between Memory and Logic",description:"Dismantling the 'HBM = next TSMC' narrative across three dimensions \u2014 business model, industry cyclicality, and geopolitics \u2014 and warning of valuation misalignment at the cycle peak.",source:"@site/i18n/en/docusaurus-plugin-content-docs/current/TechNotes/HBM \u4e0d\u662f\u4e0b\u4e00\u500b\u53f0\u7a4d\u96fb\uff1a\u8a18\u61b6\u9ad4\u8207\u908f\u8f2f\u6676\u7247\u7684\u7d50\u69cb\u6027\u9d3b\u6e9d.md",sourceDirName:"TechNotes",slug:"/TechNotes/HBM \u4e0d\u662f\u4e0b\u4e00\u500b\u53f0\u7a4d\u96fb\uff1a\u8a18\u61b6\u9ad4\u8207\u908f\u8f2f\u6676\u7247\u7684\u7d50\u69cb\u6027\u9d3b\u6e9d",permalink:"/en/docs/TechNotes/HBM \u4e0d\u662f\u4e0b\u4e00\u500b\u53f0\u7a4d\u96fb\uff1a\u8a18\u61b6\u9ad4\u8207\u908f\u8f2f\u6676\u7247\u7684\u7d50\u69cb\u6027\u9d3b\u6e9d",draft:!1,unlisted:!1,tags:[],version:"current",frontMatter:{title:"HBM Is Not the Next TSMC: The Structural Chasm Between Memory and Logic",date:"2026-05-26T00:00:00.000Z",lang:"en",section:"sober-record",topic:"t-hardware",article_tags:{zh:["\u8b77\u57ce\u6cb3","\u5546\u696d\u6a21\u5f0f","\u7b97\u529b\u7af6\u8cfd","NVIDIA","\u51fa\u53e3\u7ba1\u5236"],en:["moat","business-model","compute-race","nvidia","export-control"]},keywords:["HBM","TSMC","SK Hynix","memory cycle","semiconductor industry structure"],summary:"Dismantling the 'HBM = next TSMC' narrative across three dimensions \u2014 business model, industry cyclicality, and geopolitics \u2014 and warning of valuation misalignment at the cycle peak.",status:"published",reading_time:18,description:"Dismantling the 'HBM = next TSMC' narrative across three dimensions \u2014 business model, industry cyclicality, and geopolitics \u2014 and warning of valuation misalignment at the cycle peak."},sidebar:"docs",previous:{title:"Lucid Record",permalink:"/en/docs/TechNotes/"},next:{title:"The Truth Behind 900 Layers: When Your Switch and Steam Deck Are Footing the Bill for AI",permalink:"/en/docs/TechNotes/900 \u5c64\u7684\u771f\u76f8\uff1a\u7576\u4f60\u7684 Switch \u548c Steam Deck \u5728\u66ff AI \u8cb7\u55ae"}},c={},l=[{value:"Introduction: A Seductive Analogy That Falls Apart Under Scrutiny",id:"introduction-a-seductive-analogy-that-falls-apart-under-scrutiny",level:2},{value:"Layer 1: The Fundamental Business Model Divide \u2014 Foundry Services vs. Commodity Products",id:"layer-1-the-fundamental-business-model-divide--foundry-services-vs-commodity-products",level:2},{value:"What Does TSMC Sell?",id:"what-does-tsmc-sell",level:3},{value:"What Does Memory Sell?",id:"what-does-memory-sell",level:3},{value:"Layer 2: History Doesn&#39;t Lie \u2014 Memory&#39;s Cyclical Fate",id:"layer-2-history-doesnt-lie--memorys-cyclical-fate",level:2},{value:"The &quot;Supercycle&quot; Illusion",id:"the-supercycle-illusion",level:3},{value:"Layer 3: The Strongest Counterargument \u2014 &quot;AI Demand Is Limitless; No Amount of Capacity Is Enough&quot;",id:"layer-3-the-strongest-counterargument--ai-demand-is-limitless-no-amount-of-capacity-is-enough",level:2},{value:"Layer 4: Geopolitical Positioning \u2014 The Strategic Gap Between the Brain and the Warehouse",id:"layer-4-geopolitical-positioning--the-strategic-gap-between-the-brain-and-the-warehouse",level:2},{value:"Where Is the Centre of Gravity of US Sanctions?",id:"where-is-the-centre-of-gravity-of-us-sanctions",level:3},{value:"Layer 5: How Long Can SK Hynix&#39;s Technical Lead Last?",id:"layer-5-how-long-can-sk-hynixs-technical-lead-last",level:2},{value:"The Current Lead Is Real",id:"the-current-lead-is-real",level:3},{value:"The Lead Is a &quot;Time Gap,&quot; Not a &quot;Structural Barrier&quot;",id:"the-lead-is-a-time-gap-not-a-structural-barrier",level:3},{value:"&quot;HBM4 Base Die Outsourced to TSMC&quot; = HBM Becomes Custom Silicon?",id:"hbm4-base-die-outsourced-to-tsmc--hbm-becomes-custom-silicon",level:3},{value:"Layer 6: The Fundamental Valuation Mismatch",id:"layer-6-the-fundamental-valuation-mismatch",level:2},{value:"Risk Warning: The Coming Downturn Could Be Devastating",id:"risk-warning-the-coming-downturn-could-be-devastating",level:2},{value:"Another Warning Sign: When &quot;Tech Explainers&quot; Become &quot;Buy Signals&quot;",id:"another-warning-sign-when-tech-explainers-become-buy-signals",level:2},{value:"Conclusion: Seeing HBM&#39;s Value Clearly",id:"conclusion-seeing-hbms-value-clearly",level:2}];function h(e){const t={em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",img:"img",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.img,{src:n(50353).A+"",width:"1024",height:"1536"}),"\n",(0,i.jsx)(t.img,{src:n(98195).A+"",width:"1024",height:"1536"}),"\n",(0,i.jsx)(t.img,{src:n(49814).A+"",width:"2752",height:"1536"}),"\n",(0,i.jsx)(t.img,{src:n(68443).A+"",width:"1792",height:"2400"})]}),"\n",(0,i.jsx)(t.p,{children:"Author: Nebula Walker\nDate: 26MAY2026\nMYTHOGEN ENGINE (mythogenengine.com)"}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"\ud83d\udccc Dismantling the 'HBM = next TSMC' narrative across three dimensions \u2014 business model, industry cyclicality, and geopolitics \u2014 and warning of valuation misalignment at the cycle peak."})}),"\n",(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"hbm-is-not-the-next-tsmc-the-structural-chasm-between-memory-and-logic",children:"HBM Is Not the Next TSMC: The Structural Chasm Between Memory and Logic"})}),"\n",(0,i.jsx)(t.h2,{id:"introduction-a-seductive-analogy-that-falls-apart-under-scrutiny",children:"Introduction: A Seductive Analogy That Falls Apart Under Scrutiny"}),"\n",(0,i.jsx)(t.p,{children:'Since 2025, as AI infrastructure spending entered an explosive growth phase, High Bandwidth Memory (HBM) has become the hottest buzzword in the semiconductor market. SK Hynix\'s share price has hit record after record, Samsung is scrambling to catch up, and Micron has announced its exit from the consumer memory market to go all-in on AI data centres. A compelling narrative has taken hold: "HBM is the next TSMC."'}),"\n",(0,i.jsx)(t.p,{children:"It rolls off the tongue. It doesn't survive analysis. The analogy conflates two fundamentally different business models, two entirely different moat structures, and two industry actors occupying very different positions on the geopolitical chessboard."}),"\n",(0,i.jsx)(t.p,{children:'This article does not aim to dismiss HBM\'s technological value or its short-term investment potential. Rather, it argues from the structural logic of the industry itself why memory \u2014 even HBM, with all its formidable technical complexity \u2014 can never become "the next TSMC" in any commercially meaningful sense.'}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"layer-1-the-fundamental-business-model-divide--foundry-services-vs-commodity-products",children:"Layer 1: The Fundamental Business Model Divide \u2014 Foundry Services vs. Commodity Products"}),"\n",(0,i.jsx)(t.h3,{id:"what-does-tsmc-sell",children:"What Does TSMC Sell?"}),"\n",(0,i.jsx)(t.p,{children:'TSMC is the world\'s largest pure-play foundry. It does not design chips; it only manufactures them. But this "only manufacturing" positioning is precisely what constitutes its deepest moat.'}),"\n",(0,i.jsx)(t.p,{children:"Every chip produced at TSMC \u2014 whether Apple's A-series processors, NVIDIA's H200 / B200 GPUs, or AMD's EPYC server processors \u2014 is a bespoke product designed by the customer. TSMC provides what can be called \"heterogeneous services\": enabling mass production of different designs from different customers at extreme precision process nodes. The relationship between customer and foundry is one of deep lock-in: once a chip design completes tape-out on TSMC's 3nm or 2nm process, migrating to another foundry is tantamount to starting from scratch."}),"\n",(0,i.jsx)(t.p,{children:"This lock-in manifests directly in TSMC's financials. In full-year 2025, TSMC posted revenue of US$122.4 billion, a gross margin of 59.9%, and an operating margin of 50.8%. By Q1 2026, gross margin climbed to 66.2% with an operating margin of 58.1%. Q2 guidance projects gross margins of 65.5% to 67.5%. This is not a cyclical peak \u2014 it is structural pricing power. When your customers cannot leave, you can raise prices continuously."}),"\n",(0,i.jsx)(t.h3,{id:"what-does-memory-sell",children:"What Does Memory Sell?"}),"\n",(0,i.jsx)(t.p,{children:"Memory \u2014 including conventional DRAM and HBM \u2014 is fundamentally a commodity. Its specifications are defined by JEDEC, the international standards body. In April 2025, JEDEC officially published the HBM4 standard (JESD270-4), specifying interface width (2,048-bit), data rates (up to 8 Gb/s), stacking configurations (4/8/12/16 layers), voltage ranges, and other key parameters. In other words, as long as any memory manufacturer can produce a product that meets these specifications, it is functionally interchangeable."}),"\n",(0,i.jsxs)(t.p,{children:["This is not to say HBM lacks technical barriers. Through-silicon via (TSV) stacking, micro-bump interconnects, thermal management, yield control \u2014 these are formidable engineering challenges. But the critical distinction is this: these challenges exist at the ",(0,i.jsx)(t.em,{children:"engineering execution"})," level, not the ",(0,i.jsx)(t.em,{children:"architectural"})," level. Once a competitor catches up on execution, the product becomes a spec-compliant commodity, and the customer gains both the ability and the incentive to switch suppliers."]}),"\n",(0,i.jsx)(t.p,{children:"This is the most fundamental divide between the memory industry and logic foundry: TSMC's customers cannot leave because their designs are tailor-made for TSMC's process. Memory customers can leave because they are buying standardised products that meet a common specification."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"layer-2-history-doesnt-lie--memorys-cyclical-fate",children:"Layer 2: History Doesn't Lie \u2014 Memory's Cyclical Fate"}),"\n",(0,i.jsx)(t.h3,{id:"the-supercycle-illusion",children:'The "Supercycle" Illusion'}),"\n",(0,i.jsx)(t.p,{children:'Every time memory prices surge, the market produces voices proclaiming "this time is different." From 2017 to 2018, DRAM prices soared, and the industry proclaimed a "supercycle," claiming that structural demand from smartphones and cloud computing would break the traditional boom-bust pattern. By 2019, demand growth slowed, inventories ballooned, and average selling prices (ASPs) collapsed across the board. Micron\'s DRAM ASP fell 30% year-over-year, and earnings per share plunged 84%.'}),"\n",(0,i.jsx)(t.p,{children:"In 2022, the memory industry entered another severe downturn. Inventories swelled, prices hit rock bottom, and manufacturers posted massive losses. SK Hynix recorded an operating margin of negative 20% in Q3 2023."}),"\n",(0,i.jsx)(t.p,{children:'Then AI arrived. HBM demand exploded. DRAM prices in Q4 2025 nearly tripled compared to a year earlier. SK Hynix\'s full-year 2025 operating margin surged to 49%, hitting 58% in Q4. The market once again proclaimed: "This time it really is different."'}),"\n",(0,i.jsx)(t.p,{children:"But from a structural perspective, the underlying mechanism driving this cycle has never changed. The memory industry's fate is this: when prices are high, manufacturers inevitably expand capacity. When that capacity comes online 18 to 24 months later, if demand growth cannot keep pace, oversupply returns. Moreover, once capacity is built, the enormous fixed costs make it impossible for manufacturers to simply halt production \u2014 they can only slash prices to defend market share, further accelerating the price decline."}),"\n",(0,i.jsx)(t.p,{children:"All three major memory manufacturers are currently expanding aggressively. Samsung plans to increase HBM production capacity by approximately 50% in 2026, with its Pyeongtaek P5 fab expected to begin production in 2028. SK Hynix's M15X fab is scheduled to come online by mid-2027, with infrastructure investment expanding to more than four times the original plan. TechInsights projects the memory industry could enter another downturn as early as 2027."}),"\n",(0,i.jsx)(t.p,{children:"Contrast this with TSMC: TSMC's customers are queuing for capacity, TSMC holds the pricing power to proactively raise prices, and gross margins are climbing quarter after quarter. Memory manufacturers, meanwhile, are expanding furiously at the cycle peak, waiting to slaughter each other in the next trough. These are two entirely different commercial ecosystems."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"layer-3-the-strongest-counterargument--ai-demand-is-limitless-no-amount-of-capacity-is-enough",children:'Layer 3: The Strongest Counterargument \u2014 "AI Demand Is Limitless; No Amount of Capacity Is Enough"'}),"\n",(0,i.jsx)(t.p,{children:"This is currently the most powerful argument in defence of HBM, and the one that most urgently needs rigorous examination. It is not wrong \u2014 it is half-right."}),"\n",(0,i.jsx)(t.p,{children:"The present reality is indeed one of undersupply. All three manufacturers' HBM capacity is sold out through 2026. NVIDIA has even cut consumer GPU production (RTX 50 series output reduced 30\u201340% in H1), redirecting memory capacity to AI data centres. SK Hynix expects 2025 HBM shipments to double year-over-year. AI is projected to consume nearly 20% of global DRAM wafer capacity in 2026 (adjusted for HBM's 4x wafer consumption). These are all facts."}),"\n",(0,i.jsx)(t.p,{children:'But "can\'t buy enough now" does not equal "can never buy enough." For the logic of "demand will always exceed supply" to hold, the following conditions must all be true simultaneously and continuously:'}),"\n",(0,i.jsx)(t.p,{children:"First, Big Tech's AI capital expenditure must maintain its current growth rate. Combined capex from Meta, Google, Microsoft, and Amazon in 2024\u20132025 has already reached astronomical levels. But management teams at these companies will eventually have to justify AI investment returns to shareholders. The moment AI monetisation cannot keep pace with infrastructure spending \u2014 not that AI is useless, but that \"returns aren't fast enough to justify this burn rate\" \u2014 capex growth will decelerate. It doesn't need to stop. As long as the growth rate slows, HBM's supply-demand equation loosens."}),"\n",(0,i.jsx)(t.p,{children:'Second, AI models\' memory efficiency must not improve significantly. But in fact, the entire industry is working toward "doing more with less memory" \u2014 model compression, quantisation, sparsity, mixed-precision inference. If the next generation of models requires only half the HBM for equivalent performance, the demand growth curve gets flattened by technological progress.'}),"\n",(0,i.jsx)(t.p,{children:"Third, no alternative architectures can emerge. All mainstream AI accelerators currently depend on HBM, but that doesn't mean they always will. Processing-in-Memory, CXL memory pooling, even photonic computing \u2014 these technology directions are all attempting to circumvent HBM's bottleneck. They won't mature in the short term, but their mere existence demonstrates that HBM's \"irreplaceability\" has a time window."}),"\n",(0,i.jsx)(t.p,{children:'The more fundamental issue is this: even if demand truly does keep exploding, "undersupply" will not protect memory manufacturers\' margins forever. Because the manufacturer behaviour triggered by undersupply is precisely aggressive expansion \u2014 which is exactly what we are watching happen in real time. Samsung adding 50% capacity, SK Hynix quadrupling infrastructure investment, Micron exiting the consumer market to go all-in. Everyone is betting in the same direction, and the size of those bets far exceeds any previous cycle. When this capacity comes online en masse in 18 to 24 months, even a slight deceleration in demand growth will cause the supply-demand balance to flip in very short order.'}),"\n",(0,i.jsx)(t.p,{children:'So the correct version of this counterargument should be: "AI demand has extended the duration of this HBM upcycle." That is true. AI may make this cycle longer than any before \u2014 extending it from the typical 2\u20133 years to 4\u20135 years. But "extending" and "eliminating" are two different things. It has delayed the arrival of the cycle\'s inflection point, but it has not abolished the cycle\'s operating mechanism. TSMC\'s pricing power, by contrast, does not depend on the cycle. Whether AI demand is surging or cooling, customers\' chip designs remain locked into TSMC\'s process. This is the essential difference between a structural moat and a cyclical tailwind.'}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"layer-4-geopolitical-positioning--the-strategic-gap-between-the-brain-and-the-warehouse",children:"Layer 4: Geopolitical Positioning \u2014 The Strategic Gap Between the Brain and the Warehouse"}),"\n",(0,i.jsx)(t.h3,{id:"where-is-the-centre-of-gravity-of-us-sanctions",children:"Where Is the Centre of Gravity of US Sanctions?"}),"\n",(0,i.jsx)(t.p,{children:"Examining the semiconductor export controls the United States has imposed on China since October 2022, a clear hierarchy of priorities emerges."}),"\n",(0,i.jsx)(t.p,{children:"The core targets are logic chips and their manufacturing ecosystem. The Bureau of Industry and Security (BIS) controls cover: advanced logic ICs (non-planar transistor architectures below 16/14nm), GPUs and AI accelerators (defined by total processing performance and performance density), EDA design software (particularly tools targeting sub-3nm GAA architectures), and semiconductor manufacturing equipment (SME). The US has further coordinated with Japan and the Netherlands to restrict ASML's EUV lithography equipment exports."}),"\n",(0,i.jsx)(t.p,{children:'The strategic logic of this control framework is crystal clear: logic chips are the "brain" \u2014 the source of all AI computational power. Control the design tools, manufacturing equipment, and foundry capabilities for logic chips, and you control the lifeline of AI development.'}),"\n",(0,i.jsx)(t.p,{children:"Memory is of course also within the scope of controls \u2014 BIS has export restrictions on DRAM below 18nm half-pitch and NAND with more than 128 layers. But in terms of the allocation of enforcement intensity, memory's strategic priority is clearly lower than logic. The reason is straightforward: memory is the \"warehouse\" \u2014 a supporting role. Without it, the brain can't run at full speed; but with it, without the brain, nothing runs at all. In the geopolitical semiconductor contest, logic chips are the opening move; memory is the follow-up support."}),"\n",(0,i.jsx)(t.p,{children:'This hierarchy gap is itself a structural negation of the proposition "HBM = the next TSMC."'}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"layer-5-how-long-can-sk-hynixs-technical-lead-last",children:"Layer 5: How Long Can SK Hynix's Technical Lead Last?"}),"\n",(0,i.jsx)(t.h3,{id:"the-current-lead-is-real",children:"The Current Lead Is Real"}),"\n",(0,i.jsx)(t.p,{children:"As of Q4 2025, SK Hynix held approximately 53% to 57% of the HBM market. It is NVIDIA's primary HBM supplier, the first to mass-produce HBM3E, and the first to complete HBM4 development, claiming a 40% improvement in power efficiency and data transfer rates of 10 Gbps. Full-year 2025 revenue reached KRW 97.15 trillion, operating profit KRW 47.21 trillion, with a full-year operating margin of 49% and a Q4 operating margin soaring to 58%. These are impressive numbers."}),"\n",(0,i.jsx)(t.p,{children:"But the question is: what is the nature of this lead?"}),"\n",(0,i.jsx)(t.h3,{id:"the-lead-is-a-time-gap-not-a-structural-barrier",children:'The Lead Is a "Time Gap," Not a "Structural Barrier"'}),"\n",(0,i.jsx)(t.p,{children:"TSMC's lead is structural \u2014 its process technology, the deep design lock-in with customers, and the resulting switching costs form a moat that competitors find nearly impossible to cross. Customers don't stay because they want to; they stay because they cannot leave."}),"\n",(0,i.jsx)(t.p,{children:"SK Hynix's lead stems from a \"first-mover time gap\": it established its partnership with NVIDIA earlier than Samsung and Micron, achieved breakthroughs in TSV stacking yields earlier, and cleared NVIDIA's rigorous qualification process earlier. But this lead does not constitute structural irreplaceability."}),"\n",(0,i.jsx)(t.p,{children:"The evidence is already emerging. In September 2025, Samsung's 12-layer HBM3E passed NVIDIA's qualification testing. By Q3, Samsung's HBM market share jumped from 15% to 22%. In October 2025, Samsung announced that its 2026 HBM4 capacity was fully sold out and that it had submitted HBM4 engineering samples to NVIDIA. For its part, NVIDIA \u2014 just one week after locking in its 2026 supply contract with SK Hynix \u2014 invited Samsung into HBM4 price negotiations."}),"\n",(0,i.jsx)(t.p,{children:"The signal could not be clearer: NVIDIA, as the world's largest HBM buyer, is actively qualifying a second and even third supplier. This is not because it is dissatisfied with SK Hynix, but because no rational enterprise would allow the supply of a critical component to concentrate in a single vendor. Diversifying risk and driving down procurement costs \u2014 this is basic supply chain management."}),"\n",(0,i.jsx)(t.p,{children:"And this is precisely the key distinction between memory (commodity) and logic foundry (heterogeneous service). NVIDIA can switch HBM suppliers among SK Hynix, Samsung, and Micron because they all follow the same JEDEC standard. But NVIDIA cannot easily move a GPU that completed tape-out on TSMC's 3nm process to Samsung Foundry or Intel Foundry. The former is supplier management; the latter is strategic lock-in."}),"\n",(0,i.jsx)(t.h3,{id:"hbm4-base-die-outsourced-to-tsmc--hbm-becomes-custom-silicon",children:'"HBM4 Base Die Outsourced to TSMC" = HBM Becomes Custom Silicon?'}),"\n",(0,i.jsx)(t.p,{children:'A particularly misleading argument has recently circulated: because the HBM4 base die will for the first time be manufactured by foundries like TSMC using advanced process nodes, HBM is no longer a "commodity sold by the kilogram" but has been elevated to "custom semiconductor" \u2014 implying that HBM is acquiring moat characteristics similar to logic chips.'}),"\n",(0,i.jsx)(t.p,{children:"This reasoning conflates two distinct things."}),"\n",(0,i.jsxs)(t.p,{children:["Outsourcing the base die to TSMC changes HBM's ",(0,i.jsx)(t.em,{children:"manufacturing supply chain"}),", not its ",(0,i.jsx)(t.em,{children:"commercial nature"}),". The base die does require more advanced process technology to improve signal processing and power efficiency, but it is still a component designed to the JEDEC HBM4 standard specification (JESD270-4). TSMC's role here is to foundry-manufacture a standardised component on behalf of the memory vendor \u2014 not to accept a bespoke, customer-exclusive design locked to a specific process, as it does when manufacturing NVIDIA's GPUs. SK Hynix can use TSMC for its base die; Samsung can use its own foundry line; Micron can use a third party. When the final product ships, NVIDIA's acceptance criterion is: does your HBM4 meet spec? If it does, you are one of the qualified suppliers."]}),"\n",(0,i.jsx)(t.p,{children:"The base die's process upgrade raises HBM's technical barrier but does not change the final product's commodity nature of \"meet-spec-and-you're-interchangeable.\" High technical difficulty means a higher barrier to entry \u2014 it does not mean that products from those who clear the barrier are differentiated. If all three players can produce HBM4 that meets spec, customers have both the ability and the incentive to switch. This is fundamentally different from TSMC's situation \u2014 where customers' chip designs are physically locked to its process and cannot be moved."}),"\n",(0,i.jsx)(t.p,{children:'Equating "a more complex manufacturing supply chain" with "a deeper commercial moat" is the most common \u2014 and most dangerous \u2014 logical slippage in this cycle\'s HBM narrative.'}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"layer-6-the-fundamental-valuation-mismatch",children:"Layer 6: The Fundamental Valuation Mismatch"}),"\n",(0,i.jsx)(t.p,{children:'When the market draws an analogy between HBM and "the next TSMC," the implicit assumption is that memory manufacturers will earn a TSMC-like structural premium \u2014 sustained high gross margins, stable revenue growth, and pricing power immune to cyclical fluctuations.'}),"\n",(0,i.jsx)(t.p,{children:"But the data tells a different story."}),"\n",(0,i.jsx)(t.p,{children:"TSMC's full-year 2025 gross margin was 59.9%, climbing to 66.2% in Q1 2026, and continuing to rise on the back of its process leadership. Micron's gross margin over the same period climbed from 36.8% in Q2 2025 to approximately 44.5% by Q4 \u2014 already an excellent performance for the memory industry at a cycle peak. SK Hynix's Q4 2025 operating margin reached 58%, seemingly approaching TSMC's level. But note: this figure was achieved under extreme conditions of HBM undersupply and sharply rising ASPs."}),"\n",(0,i.jsx)(t.p,{children:"Compare this to two years earlier \u2014 in Q3 2023, SK Hynix's operating margin was negative 20%. A violent swing from -20% to +58% is itself the defining hallmark of cyclical industries. TSMC's gross margin, even during the semiconductor industry's most depressed periods, has never fallen below 40%."}),"\n",(0,i.jsx)(t.p,{children:"If you apply TSMC's valuation logic to a memory company, you are effectively paying a moat-stock premium for a cyclical stock. This is not investing \u2014 it is betting that the next cycle peak will be even higher."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"risk-warning-the-coming-downturn-could-be-devastating",children:"Risk Warning: The Coming Downturn Could Be Devastating"}),"\n",(0,i.jsxs)(t.p,{children:["If the analysis above were merely academic, there would be little point in writing it. But it isn't. It points to a very specific, existential risk for current holders: ",(0,i.jsx)(t.strong,{children:"the severity of the coming downturn will very likely exceed historical averages."})]}),"\n",(0,i.jsx)(t.p,{children:"The logic is simple: the longer the upcycle is extended by AI demand, the larger the scale of capacity expansion that manufacturers accumulate at the peak. In a normal cycle, manufacturers begin to feel supply-demand reversal pressure after about two years of expansion, and capital expenditure exercises some degree of self-restraint. But this time is different. Because demand has continued to explode for so long, manufacturer confidence has been reinforced repeatedly, and the scale of expansion has grown bolder and bolder. Samsung adding 50% capacity, SK Hynix quadrupling infrastructure, Micron pivoting entirely to AI \u2014 everyone is betting in the same direction, and the magnitude of those bets far exceeds any previous cycle."}),"\n",(0,i.jsx)(t.p,{children:"Semiconductor capacity has a cruel time-lag characteristic: investment decisions are made today, but capacity comes online 18 to 24 months later. Today's frenzied undersupply is essentially pre-loading ammunition for the oversupply of 2027\u20132028."}),"\n",(0,i.jsx)(t.p,{children:"The typical pattern of memory downturns is: operating margins fall from above 50% to 20% or even turn negative, share prices begin their decline 1 to 2 quarters before fundamentals deteriorate, and the drawdown typically reaches 50% to 60%. In 2019, Micron's EPS plunged 84%. In 2023, SK Hynix's operating margin cratered from its peak to negative 20%."}),"\n",(0,i.jsx)(t.p,{children:'This time, every amplifying factor is larger than before: the upcycle is longer, the expansion is larger, the valuation bubble is thicker, and retail participation is higher. When the turn comes \u2014 not "if" but "when" \u2014 the speed and depth of the decline will very likely set a new record for the memory industry.'}),"\n",(0,i.jsx)(t.p,{children:'The most exposed are those investors who entered at the cycle peak. What they see is SK Hynix at a 58% operating margin, HBM capacity fully sold out, and the narrative of "limitless AI demand," leading them to believe they are buying a "secular trend." What they have actually bought is a cyclical stock at a historic peak, for which they are paying a moat-stock valuation premium.'}),"\n",(0,i.jsx)(t.p,{children:'The cruelty of cyclical stocks is this: they don\'t give advance notice of the inflection point. By the time you confirm the downturn has begun, the share price has already been falling for two quarters. And because the AI-extended upcycle is so long, many investors will interpret the first wave of declines as a "pullback," continuing to hold or even adding to their positions \u2014 only to be fully trapped in the second and third waves of decline.'}),"\n",(0,i.jsx)(t.p,{children:"This is not alarmism. This is the script the memory industry has performed in every cycle for the past thirty years. The only difference is that this time, the script may be rewritten in much larger font."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"another-warning-sign-when-tech-explainers-become-buy-signals",children:'Another Warning Sign: When "Tech Explainers" Become "Buy Signals"'}),"\n",(0,i.jsx)(t.p,{children:"If manufacturers' aggressive expansion represents the supply-side risk signal, then what is happening on social media represents the demand-side \u2014 retail capital-side \u2014 risk signal."}),"\n",(0,i.jsx)(t.p,{children:"Observe the content ecosystem surrounding memory stocks on Chinese-language social media, and a pattern worth heeding becomes visible."}),"\n",(0,i.jsx)(t.p,{children:'One category is tech industry influencers. Their primary work involves AI tool deployment, enterprise consulting, and technology evangelism; they carry considerable influence and credibility within tech circles and government organisations. But when they post screenshots of single-day gains on memory stocks on social media with captions like "my big brother delivered again," the signal transmitted to their followers is no longer "technical analysis" but "even the tech experts are making money \u2014 why aren\'t you in yet?" They may not intend to be shilling, but the effect is identical \u2014 because their audience trusts their "tech expertise," and that trust extends indiscriminately to investment judgment.'}),"\n",(0,i.jsx)(t.p,{children:'Another category is consumer tech and unboxing channels. The content they produce is fundamentally educational \u2014 the technical principles of memory, why SSD prices are rising, the differences between NAND and HBM \u2014 and when done well, it genuinely makes complex subjects accessible to laypeople. But when the conclusion slides from "that\'s the technical explanation" to "memory has become a strategic resource like oil," "buying now is the cheapest it\'ll ever be," or even "if you think SSDs are overpriced, buy memory stocks to hedge" \u2014 the nature of the content has changed completely. It is no longer education but an investment pitch dressed in the clothing of expertise. The impression viewers take away is not "cyclical stocks are dangerous" but "this sector is safe \u2014 the experts all say so."'}),"\n",(0,i.jsx)(t.p,{children:'Even more concerning is the indiscriminate contagion of sector narratives. HBM\'s undersupply is used to justify NAND Flash share prices. GPU compute demand is used to argue that SSD pricing is rational. Companies across different subsectors, different business models, and different cycle positions are packaged into a single "AI memory concept stock" narrative, all enjoying the same valuation premium. This kind of sector-wide mania has appeared in every tech bubble in history \u2014 in the .com bubble of 2000, in the metaverse mania of 2021, and now in AI memory.'}),"\n",(0,i.jsx)(t.p,{children:'When the market begins describing a product that can be expanded, substituted, and is governed by cycles as a "strategic resource," it is usually the most dangerous signal of a cycle top. Not because fundamentals are bad \u2014 quite the opposite; fundamentals at the top are typically the most dazzling. But because when everyone believes "this time is different," no one prepares for the downside. And those who don\'t prepare run the slowest and get hurt the deepest when the cycle turns.'}),"\n",(0,i.jsx)(t.p,{children:'The cruellest aspect of this information bubble is this: it\'s not that no one tells the truth \u2014 it\'s that the volume of truth is completely drowned out by emotion. Open the comments section of any popular memory tech explainer video, and you\'ll find hundreds of comments like "glad I bought early," "already up six figures," and "buying now is still cheap," while the one or two sober analyses mentioning cyclical risk are buried in the flood of FOMO, barely getting any likes at all. This is how information bubbles operate \u2014 they don\'t need to suppress dissent; they only need the volume of emotion to drown it out.'}),"\n",(0,i.jsx)(t.p,{children:'Of course, I harbour no illusions about this. This article\'s reach will almost certainly lose to a single attractive screenshot of a day\'s gains. In the world of algorithms, a ten-thousand-word structural analysis will never outperform a green candlestick chart adorned with a rocket emoji. But if you happen to be the kind of person who, while everyone else is shouting "get on board," feels a faint sense that "something isn\'t right" \u2014 then this article was written for you.'}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"conclusion-seeing-hbms-value-clearly",children:"Conclusion: Seeing HBM's Value Clearly"}),"\n",(0,i.jsx)(t.p,{children:"HBM is a remarkable technological achievement. It plays an indispensable role in AI infrastructure. SK Hynix's execution and first-mover advantage in this space deserve respect."}),"\n",(0,i.jsx)(t.p,{children:'But "indispensable" does not mean "irreplaceable." "High technical difficulty" does not mean "deep moat." "Currently profitable" does not mean "durably profitable."'}),"\n",(0,i.jsx)(t.p,{children:"Memory is a commodity, governed by cycles, with switchable suppliers. Logic foundry is a heterogeneous service, bound by ecosystem lock-in, with unswitchable suppliers. These are two entirely different commercial species. The former is the warehouse; the latter is the brain. The former's value depends on supply-demand balance; the latter's value depends on irreplaceability."}),"\n",(0,i.jsx)(t.p,{children:"HBM is a good business, but it is not the next TSMC. Those who conflate the two either do not understand the depth of the foundry model's moat or do not understand the cyclical fate of the memory industry."}),"\n",(0,i.jsx)(t.p,{children:"And as clear-eyed observers, what we must do is this: acknowledge HBM's short-term value while refusing to mistake a cyclical peak for a structural moat."})]})}function d(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(h,{...e})}):h(e)}},98195(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/ChatGPT Image 2026\u5e745\u670827\u65e5 \u4e0a\u534810_10_05-0ac147fecf5e3c9e901943bd41289070.jpg"},50353(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/ChatGPT Image 2026\u5e745\u670827\u65e5 \u4e0a\u534810_15_57-eaca54f9ef9666a9156a095df8f3bf1d.jpg"},49814(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/Gemini_Generated_Image_fr320bfr320bfr32-aeac325db4c5a33ec9f3e27d7460571e.jpg"},68443(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/Gemini_Generated_Image_sgkitasgkitasgki-4d19a0b2ec6e2a579c32f028b8474074.jpg"},28453(e,t,n){n.d(t,{R:()=>r,x:()=>o});var i=n(96540);const s={},a=i.createContext(s);function r(e){const t=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),i.createElement(a.Provider,{value:t},e.children)}}}]);